class PastedList
  STEPS = %i[strip_line drop_bullet build_item].freeze

  def initialize(text, steps: STEPS)
    @text = text
    @steps = steps
  end

  def items
    @text.to_s.lines.filter_map do |line|
      @steps.reduce(line) { |value, step| value && send(step, value) }
    end
  end

  private

  def strip_line(line) = line.strip.presence
  def drop_bullet(line) = line.delete_prefix("- ").strip.presence
  def build_item(name) = { name: name, quantity: 1 }
end
